if (c === ')') {
  if (acc === '' && ast.#parts.length === 0) {
    ast.#emptyExt = true
  }
  part.push(acc)
  acc = ''
  ast.push(...parts, part)
  return i

#adopt(
  child: AST & {
    type: null
  },
  index: number,
) {
  const gc = child.#parts[0] as AST & { type: ExtglobType }
  this.#parts.splice(index, 1, ...gc.#parts)
  for (const p of gc.#parts) {
    if (typeof p === 'object') p.#parent = this
  }
  this.#toString = undefined
}
